<template><div class="grid gap-0 xl:grid-cols-[minmax(0,1.25fr)_360px]"><div class="border-b border-slate-200/70 p-5 dark:border-slate-700 xl:border-b-0 xl:border-r"><div class="flex items-center justify-between"><div><h3 class="text-sm font-800">Quote setup</h3><p class="mt-1 text-xs text-slate-500">The essentials suppliers need to respond.</p></div><span class="text-[10px] font-bold text-slate-400">Auto-saved</span></div><div class="mt-4 grid gap-4 md:grid-cols-2"><label><span class="mb-1.5 block text-xs font-bold">Deadline</span><input :value="deadlineDate" type="date" class="field" @change="$emit('update:deadline', $event.target.value)" /></label><label><span class="mb-1.5 block text-xs font-bold">Visibility</span><select v-model="event.visibility" class="field" @change="$emit('record', 'Visibility updated', event.visibility)"><option>Public</option><option>Private</option><option>Restricted</option></select></label><label><span class="mb-1.5 block text-xs font-bold">Savings target</span><div class="relative"><input v-model.number="event.savingsTarget" type="number" min="0" max="100" class="field pr-8" @change="$emit('record', 'Savings target updated', event.savingsTarget + '%')" /><span class="absolute right-3 top-2 text-sm text-slate-400">%</span></div></label><label class="flex items-center gap-3 rounded-xl border border-slate-200/70 p-3 dark:border-slate-700"><input v-model="event.autoExtend" type="checkbox" class="h-4 w-4 accent-[var(--accent)]" /><span><b class="block text-xs">Auto-extend deadline</b><small class="text-[10px] text-slate-500">Protect late supplier activity.</small></span></label></div><div class="mt-6 flex items-center justify-between"><div><h3 class="text-sm font-800">Items to quote</h3><p class="mt-1 text-xs text-slate-500">These items stay consistent through offers and selection.</p></div><button class="text-xs font-bold text-brand" @click="$emit('add-lot')"><i class="fa-solid fa-plus mr-1"></i>Add item group
